package net.officefloor.hq.app.statement;

/** Only a steward cancels a statement, and only a person with one has a statement to cancel. */
public class StatementCancelRefusedException extends RuntimeException {

    public StatementCancelRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people/{personId}/statement")
public class StatementController {

    /** A statement taken: the person's statements as their row shows them, and their claims,
     *  newest first, as it bound them. */
    public record StatementTaken(StatementSummary statements, List<ClaimView> claims) {
    }

    /** A statement to take: as of a day (blank: now). */
    public record StatementRequest(LocalDate asOf) {
    }

    private final StatementService service;

    private final RollupService rollups;

    private final ClaimService claimService;

    public StatementController(StatementService service, RollupService rollups, ClaimService claimService) {
        this.service = service;
        this.rollups = rollups;
        this.claimService = claimService;
    }

    /** Take a statement for the person, now or as of a day. */
    @PostMapping
    public StatementTaken take(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody(required = false) StatementRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        LocalDate asOf = request != null ? request.asOf() : null;
        List<ClaimView> claims = rollups.track(sheet, by, () -> service.take(sheet, by, personId, asOf)).stream()
                .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                        claimService.logOf(claim.getId()), claimService.commentsOf(claim.getId()),
                        claimService.linesOf(claim.getId()))).toList();
        return new StatementTaken(service.summary(sheet, personId), claims);
    }

    /** Cancel the person's last statement: their statements as their row then shows them, and their
     *  claims, newest first, now live again. */
    @DeleteMapping
    public StatementTaken cancel(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long personId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        List<ClaimView> claims = rollups.track(sheet, by, () -> service.cancel(sheet, by, personId)).stream()
                .map(claim -> ClaimView.of(claim, claimService.roundsBy(sheet, claim),
                        claimService.logOf(claim.getId()), claimService.commentsOf(claim.getId()),
                        claimService.linesOf(claim.getId()))).toList();
        return new StatementTaken(service.summary(sheet, personId), claims);
    }

    @ExceptionHandler(StatementRefusedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void refusedAsOf() {
    }

    @ExceptionHandler(StatementCancelRefusedException.class)
    @ResponseStatus(HttpStatus.FORBIDDEN)
    public void refused() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A statement taken for a person: the sheet's today when it was taken, their due-total then (two
 *  decimals, or n/a) and how many of their claims counted. */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    @Column(name = "claims", nullable = false)
    private int claims;

    /** The sheet's today when the statement was taken; null for one taken before it was kept. */
    @Column(name = "made_on", updatable = false)
    private LocalDate madeOn;

    /** The sheet's today when the statement was cancelled; null while it stands. */
    @Column(name = "cancelled_on")
    private LocalDate cancelledOn;

    /** Where the statement falls among its person's statements; null: by its id. */
    @Column(name = "ordinal")
    private Long ordinal;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, LocalDate takenOn, String dueTotal, int claims, LocalDate madeOn) {
        this.madeOn = madeOn;
        this.sheetId = sheetId;
        this.personId = personId;
        this.takenOn = takenOn;
        this.dueTotal = dueTotal;
        this.claims = claims;
    }

    public Long getId() {
        return id;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Where the statement falls among its person's statements: the last is the highest. */
    public long getOrder() {
        return ordinal != null ? ordinal : id;
    }

    /** Move the statement to another person, falling at an order among their statements. */
    public void moveTo(Long personId, long order) {
        this.personId = personId;
        this.ordinal = order;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public String getDueTotal() {
        return dueTotal;
    }

    /** Whether the statement stood at the end of a day: taken while the sheet's today was on or before
     *  it (one taken before that was kept: dated on or before it). */
    public boolean madeAsOf(LocalDate day) {
        return !(madeOn != null ? madeOn : takenOn).isAfter(day);
    }

    /** Whether the statement stands now: it was not cancelled. */
    public boolean isLive() {
        return cancelledOn == null;
    }

    /** Whether the statement stood at the end of a day: made as of it, and not cancelled while the
     *  sheet's today was on or before it. */
    public boolean stoodAsOf(LocalDate day) {
        return madeAsOf(day) && (cancelledOn == null || cancelledOn.isAfter(day));
    }

    /** Cancel the statement on the sheet's today. */
    public void cancel(LocalDate today) {
        this.cancelledOn = today;
    }

    public int getClaims() {
        return claims;
    }
}
package net.officefloor.hq.app.statement;

/** A statement is taken as of a day on or before the sheet's today, for a person on the sheet then. */
public class StatementRefusedException extends RuntimeException {

    public StatementRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.statement;

import java.util.Comparator;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements, in the order they were taken. */
    List<Statement> findBySheetIdOrderByIdAsc(String sheetId);

    /** A person's statements, in the order they were taken. */
    List<Statement> findBySheetIdAndPersonIdOrderByIdAsc(String sheetId, Long personId);

    /** A person's statements, in their order: the last is their last statement. */
    default List<Statement> inOrder(String sheetId, Long personId) {
        return findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId).stream()
                .sorted(Comparator.comparingLong(Statement::getOrder)).toList();
    }
}
