        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new StatementCancelRefusedException(user + " is not a steward: only a steward cancels a statement");
        }
        List<Statement> theirs = statements.inOrder(sheetId, personId).stream()
                .filter(Statement::isLive).toList();
        if (theirs.isEmpty()) {
            throw new StatementCancelRefusedException(person.getName() + " has no statement to cancel");
        }
        Statement last = theirs.get(theirs.size() - 1);
        List<Claim> theirClaims = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
        List<Claim> bound = theirClaims.stream().filter(Claim::isStated).toList();
        bound.forEach(Claim::unbind);
        claims.saveAllAndFlush(bound);
        // Kept, marked cancelled, so the sheet as it stood at the end of an earlier day still shows it.
        last.cancel(sheets.today(sheetId));
        statements.saveAndFlush(last);
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + last.getDueTotal());
        return theirClaims;
    }
}
package net.officefloor.hq.app.statement;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;

/** A person's statements as their row shows them: how many were taken, the last one's due-total
 *  and date (null when none was taken), and a line for each, oldest first. */
public record StatementSummary(int count, String lastDueTotal, LocalDate lastDate, List<Line> lines) {

    /** One statement as its person's row lists it: its date and the due-total it recorded. */
    public record Line(LocalDate date, String dueTotal) {
    }

    public static final StatementSummary NONE = new StatementSummary(0, null, null, List.of());

    /** The summary of one person's statements, in their order (the last is their last statement). */
    public static StatementSummary of(List<Statement> statements) {
        if (statements.isEmpty()) {
            return NONE;
        }
        Statement last = statements.get(statements.size() - 1);
        // Oldest first by date, so those a merge or transfer brought over fall among the person's own.
        List<Line> lines = statements.stream()
                .sorted(Comparator.comparing(Statement::getTakenOn).thenComparingLong(Statement::getOrder))
                .map(statement -> new Line(statement.getTakenOn(), statement.getDueTotal())).toList();
        return new StatementSummary(statements.size(), last.getDueTotal(), last.getTakenOn(), lines);
    }
}
-- A statement taken for a person: the sheet's today when it was taken, the person's due-total then
-- ("n/a" when their grade had no rate and no claim of theirs kept a figure) and how many of their
-- claims counted. A person's last statement is the one with the highest id.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    taken_on DATE NOT NULL,
    due_total VARCHAR(20) NOT NULL,
    claims INT NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
CREATE INDEX statement_sheet ON statement (sheet_id, id);

-- A claim bound by its person's last statement shows and totals the figure it had then (null when
-- it had none) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(12, 2);
-- A cancelled statement is kept, marked with the sheet's today when it was cancelled, so the sheet as
-- it stood at the end of an earlier day still shows it; it no longer counts now. Null: not cancelled.
ALTER TABLE statement ADD COLUMN cancelled_on DATE;
-- Where a statement falls among its person's statements: a person's last statement is the one with the
-- highest ordinal, or id when it has none. A statement moved to another person by a merge, when that
-- person has statements of their own, is given an ordinal before theirs, so their last stays theirs.
ALTER TABLE statement ADD COLUMN ordinal BIGINT;
